CREATE TABLE learning_mode_definition (id UUID PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, display_name VARCHAR(160) NOT NULL, description CLOB NOT NULL, display_order INTEGER NOT NULL, active BOOLEAN NOT NULL, content_version INTEGER NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT chk_learning_mode_order CHECK(display_order > 0));
ALTER TABLE mode_skill_requirement ADD COLUMN learning_mode_definition_id UUID;
ALTER TABLE mode_skill_requirement ADD CONSTRAINT fk_requirement_mode_definition FOREIGN KEY(learning_mode_definition_id) REFERENCES learning_mode_definition(id);
CREATE INDEX idx_mode_definition_active_order ON learning_mode_definition(active,display_order);
INSERT INTO learning_mode_definition VALUES
